def fib_mod(n: int, m: int) -> int:
    def _fib(k):
        if k == 0:
            return (0, 1)
        a, b = _fib(k >> 1)
        c = (a * ((b << 1) - a)) % m
        d = (a * a + b * b) % m
        if k & 1:
            return (d, (c + d) % m)
        else:
            return (c, d)
    return _fib(n)[0]

